sys_ui_action.script:
(function executeRule(current, previous) {
    var errors = [];

    try {
        var orchestratorSteps = new x_snc_ai_sdlc.AIOrchestrator(current);
        orchestratorSteps.generateStakeholderTestSteps();
    } catch (e) {
        errors.push('Stakeholder test steps: ' + e.message);
    }

    try {
        var orchestratorTests = new x_snc_ai_sdlc.AIOrchestrator(current);
        orchestratorTests.generateUnitTests();
    } catch (e) {
        errors.push('Unit tests: ' + e.message);
    }

    if (errors.length === 0) {
        gs.addInfoMessage('Unit tests and stakeholder test steps generated successfully. View results on the AI Manifest record.');
    } else if (errors.length === 2) {
        gs.addErrorMessage('Both test generation steps failed. Errors: ' + errors.join(' | '));
    } else {
        gs.addInfoMessage('Partial success. Completed one of two test generation steps.');
        gs.addErrorMessage('One step failed: ' + errors[0]);
    }

    action.setRedirectURL(current);
})(current, previous);
